<?php
declare(strict_types=1);
namespace Modules\Integrations;

/** Selective received-component import. No old operation is inserted into a runnable table. */
final class CaptureImport
{
    public const TABLES=['connections_connection','connections_probedocumentfile','connections_proberun','connections_probestep','core_auditevent','external_documents_batchsettings','external_documents_collectiondocument','external_documents_collectionpage','external_documents_collectionrun','external_documents_externaldocument','external_documents_importbatch','file_storage_storedfile','file_storage_filereference','rental_onec_native_entitybinding','rental_onec_native_intentrecord','rental_onec_native_preparedoperation','rental_onec_native_sourcepacketcapture','rental_workflow_approvedwordderivative','rental_workflow_archivefile','rental_workflow_catalogattestation','rental_workflow_commandreceipt','rental_workflow_deliveryattempt','rental_workflow_deliveryinvocation','rental_workflow_deliveryreceipt','rental_workflow_existinginvoiceartifact','rental_workflow_generatedartifact','rental_workflow_legacydeliveryfence','rental_workflow_logicalfile','rental_workflow_nativeeffect','rental_workflow_nativeonecinvocation','rental_workflow_persona','rental_workflow_plannedinvoiceartifact','rental_workflow_roleprofile','rental_workflow_snapshot','rental_workflow_sourcearchive','rental_workflow_templatereservation','rental_workflow_workspace'];
    private string $directory;
    public function __construct(private \PDO $db,private PrivateStore $store,private CaptureReader $reader,string $directory) {
        if(!is_dir($directory)&&!mkdir($directory,0700,true))throw new \RuntimeException('CAPTURE_ARCHIVE_DIRECTORY_FAILED');if(is_link($directory))throw new \RuntimeException('CAPTURE_LINK_REJECTED');$this->directory=str_replace('\\','/',(string)realpath($directory));
    }
    private function privatePath(string $kind,string $sha): string {if(!preg_match('/^[a-f0-9]{64}$/D',$sha))throw new \RuntimeException('CAPTURE_HASH_INVALID');return $kind.'/'.$sha;}
    private function copy(string $path,string $sha,int $bytes,string $kind): string {$relative=$this->privatePath($kind,$sha);$this->reader->copy($path,$sha,$bytes,$this->directory.'/'.$relative);return $relative;}
    private static function value(array $row,string $key): string|bool|null {if(!array_key_exists($key,$row))throw new \RuntimeException('CAPTURE_COLUMN_MISSING');return CaptureReader::scalar($row[$key]);}
    private static function text(array $row,string $key): string {$v=self::value($row,$key);if(!is_string($v))throw new \RuntimeException('CAPTURE_STRING_REQUIRED');return $v;}
    public function run(bool $promoteDocuments=false): array {
        $lock='ipphp-capture-import';$q=$this->db->prepare('SELECT GET_LOCK(?,0)');$q->execute([$lock]);if((int)$q->fetchColumn()!==1)throw new \RuntimeException('CAPTURE_IMPORT_BUSY');try{return $this->locked($promoteDocuments);}finally{$q=$this->db->prepare('SELECT RELEASE_LOCK(?)');$q->execute([$lock]);}
    }
    private function locked(bool $promoteDocuments): array {
        $id=CaptureReader::PINS['rootpackage-manifest.json'];$old=$this->db->prepare('SELECT status,archive_only FROM integration_captures WHERE id=?');$old->execute([$id]);$existing=$old->fetch(\PDO::FETCH_ASSOC);if($existing&&$existing['status']==='complete'){if((bool)$existing['archive_only']===$promoteDocuments)throw new \RuntimeException('CAPTURE_IMPORT_MODE_CONFLICT');return ['capture_id'=>$id,'status'=>'complete','reused'=>true,'eligible'=>false,'globalPIT'=>false,'restoreReady'=>false];}if($existing)throw new \RuntimeException('CAPTURE_INCOMPLETE_RECONCILIATION_REQUIRED');
        $source=$this->reader->rootManifest;$manifest=$this->store->put('capture-manifests',Support::json(['root'=>$source,'pins'=>CaptureReader::PINS,'policy'=>'received-components-readonly-history-v1']));
        $this->db->beginTransaction();$counts=[];
        try{$this->db->prepare("INSERT INTO integration_captures(id,root_sha256,source_release,status,eligible,global_pit,restore_ready,archive_only,manifest_path) VALUES(?,?,?,'verifying',?,?,?,?,?)")->execute([$id,$id,$source['sourceRelease']??'fa907cce3ea6722cb60bc8a7436750e509715c79',(int)($source['eligible']??false),(int)($source['globalPIT']??false),(int)($source['restoreReady']??false),$promoteDocuments?0:1,$manifest]);
            foreach(self::TABLES as $table){$info=$this->reader->tableInfo($table);$path=$this->copy($info['path'],$info['sha256'],$info['bytes'],'tables');$this->db->prepare('INSERT INTO integration_capture_tables(capture_id,source_table,row_count,byte_size,sha256,private_path) VALUES(?,?,?,?,?,?)')->execute([$id,$table,$info['rows'],$info['bytes'],$info['sha256'],$path]);$count=0;$schema=$this->reader->schema($table);
                foreach($this->reader->rows($table) as $entry){$row=$entry['row'];$pk=[];foreach($schema['primaryKey'] as $key)$pk[$key]=self::value($row,$key);$pkBytes=Support::canonical($pk);$this->db->prepare('INSERT INTO integration_capture_rows(capture_id,source_table,source_pk_sha256,source_pk_json,ordinal,byte_offset,byte_size,row_sha256) VALUES(?,?,?,?,?,?,?,?)')->execute([$id,$table,hash('sha256',$pkBytes),$pkBytes,$entry['ordinal'],$entry['offset'],$entry['bytes'],$entry['sha256']]);
                    foreach($row as $column=>$cell)if(is_array($cell)&&isset($cell['status']))$this->cell($id,$table,$entry['ordinal'],$column,$cell);
                    if($table==='file_storage_storedfile')$this->blob($id,$row);
                    elseif($table==='file_storage_filereference')$this->fileReference($id,$row,$entry['ordinal']);
                    elseif($table==='external_documents_externaldocument')$this->document($id,$row,$entry['ordinal']);
                    $count++;
                }$counts[$table]=$count;
            }
            $history=(new CaptureMessageHistory($this->reader,$this->store))->import($this->db,$id);
            if($promoteDocuments)$this->promote($id);
            $this->db->prepare("UPDATE integration_captures SET status='complete',completed_at=NOW(6) WHERE id=?")->execute([$id]);$this->db->commit();return ['capture_id'=>$id,'status'=>'complete','tables'=>$counts,'message_history'=>$history,'eligible'=>$source['eligible']??null,'globalPIT'=>$source['globalPIT']??null,'restoreReady'=>$source['restoreReady']??null,'promoted_documents'=>$promoteDocuments,'historical_operations_activated'=>0];
        }catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    private function cell(string $id,string $table,int $ordinal,string $column,array $cell): void {
        $status=$cell['status'];$sha=null;$bytes=null;$path=null;$semantics=$cell['semantics']??null;
        if($status==='INCLUDED_INLINE'){$raw=$this->reader->raw($cell,$table,$ordinal,$column,65536);$path=$this->store->put('capture-cells',$raw);$sha=hash('sha256',$raw);$bytes=strlen($raw);}
        elseif($status==='INCLUDED'){$relative='sql-cells/'.$table.'/'.$ordinal.'-'.$column.'.raw';if(($cell['path']??'')!==$relative||!is_int($cell['bytes']??null))throw new \RuntimeException('CAPTURE_CELL_CONTEXT_MISMATCH');$sha=$cell['sha256']??'';$bytes=$cell['bytes'];$info=$this->reader->payloadInfo($relative,$sha,$bytes);$context=$info['context']??[];if(($context['table']??null)!==$table||($context['rowOrdinal']??null)!==$ordinal||($context['column']??null)!==$column)throw new \RuntimeException('CAPTURE_CELL_CONTEXT_MISMATCH');$semantics=$context['semantics']??null;$path=$this->copy($relative,$sha,$bytes,'cells');}
        elseif(!in_array($status,['WITHHELD_SENSITIVE_RAW','WITHHELD_FIELD_WITH_REASON'],true))throw new \RuntimeException('CAPTURE_CELL_STATUS_UNKNOWN');
        $this->db->prepare('INSERT INTO integration_capture_cells(capture_id,source_table,ordinal,source_column,source_status,semantics,sha256,byte_size,private_path) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$id,$table,$ordinal,$column,$status,$semantics,$sha,$bytes,$path]);
    }
    private function blob(string $id,array $row): void {$sha=self::text($row,'sha256');$size=self::text($row,'size');if(!ctype_digit($size)||strlen($size)>10||bccomp($size,'2147483648')>0)throw new \RuntimeException('CAPTURE_BLOB_LIMIT');$relative='objects/sha256/'.substr($sha,0,2).'/'.substr($sha,2,2).'/'.$sha;$info=$this->reader->payloadReceipt($relative,$sha,(int)$size);$available=($info['localBytesRetained']??false)===true;if($available){$this->reader->payloadInfo($relative,$sha,(int)$size);$path=$this->copy($relative,$sha,(int)$size,'blobs');}else{if(($info['status']??'')!=='UNREVIEWED_SQLITE_SCHEMA')throw new \RuntimeException('CAPTURE_UNKNOWN_WITHHELD_BLOB');$path=null;}$this->db->prepare('INSERT INTO integration_capture_blobs(capture_id,sha256,byte_size,private_path,source_status,available) VALUES(?,?,?,?,?,?)')->execute([$id,$sha,$size,$path,$info['status'],(int)$available]);}
    private function fileReference(string $id,array $row,int $ordinal): void {$provenance=$this->reader->raw($row['provenance'],'file_storage_filereference',$ordinal,'provenance');$path=$this->store->put('capture-provenance',$provenance);$this->db->prepare('INSERT INTO integration_capture_file_refs(capture_id,source_id,namespace,owner_key,role,original_name,content_type,blob_sha256,provenance_path) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$id,self::text($row,'id'),self::text($row,'namespace'),self::text($row,'owner_key'),self::text($row,'role'),self::text($row,'original_name'),self::text($row,'content_type'),self::text($row,'blob_id'),$path]);}
    private function document(string $id,array $row,int $ordinal): void {
        $raw=$this->reader->raw($row['raw_data'],'external_documents_externaldocument',$ordinal,'raw_data');$rawPath=$this->store->put('capture-documents',$raw);$provider=Support::provider(self::text($row,'provider'));if(in_array($provider,['email','max'],true))throw new \RuntimeException('CAPTURE_DOCUMENT_PROVIDER_INVALID');
        $strings=[];foreach(['id','source_id','identity_sha256','batch_id','document_date','number','status','account_id','account','document_type'] as $key)$strings[$key]=self::text($row,$key);
        foreach(['title','address','sender','recipient'] as $key)$strings[$key]=is_array($row[$key])?$this->reader->raw($row[$key],'external_documents_externaldocument',$ordinal,$key):self::text($row,$key);
        $amount=self::value($row,'amount');$amount=$amount===null?null:Support::money($amount);
        $this->db->prepare('INSERT INTO integration_capture_documents(capture_id,source_id,provider,native_source_id,identity_sha256,batch_source_id,document_date,number,title,amount,status,account_id,account_display,address,sender,recipient,document_type,raw_path,raw_sha256) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$strings['id'],$provider,$strings['source_id'],$strings['identity_sha256'],$strings['batch_id'],$strings['document_date'],$strings['number'],$strings['title'],$amount,$strings['status'],$strings['account_id'],$strings['account'],$strings['address'],$strings['sender'],$strings['recipient'],$strings['document_type'],$rawPath,hash('sha256',$raw)]);
    }
    private function promote(string $id): void {
        $q=$this->db->prepare('SELECT * FROM integration_capture_documents WHERE capture_id=? ORDER BY source_id');$q->execute([$id]);foreach($q->fetchAll(\PDO::FETCH_ASSOC) as $d){$cutoff=$d['provider']==='onec'?'2026-09-01':'2026-10-01';if($d['document_date']<$cutoff)continue;if(!preg_match('/^[a-f0-9]{32}$/Di',$d['source_id']))throw new \RuntimeException('CAPTURE_DOCUMENT_UUID_REQUIRED');$target=$d['source_id'];$test=$this->db->prepare('SELECT id,raw_sha256 FROM external_documents WHERE id=? OR (provider=? AND source_id=?)');$test->execute([$target,$d['provider'],$d['native_source_id']]);if($test->fetch())throw new \RuntimeException('CAPTURE_TARGET_IDENTITY_CONFLICT');
            $context=$this->store->put('contexts',Support::json(['capture_id'=>$id,'source_table'=>'external_documents_externaldocument','source_id'=>$d['source_id'],'source_identity_sha256'=>$d['identity_sha256'],'source_batch_id'=>$d['batch_source_id'],'raw_semantics'=>'STORED_JSON_SEMANTICS_NOT_HTTP_WIRE']));
            $this->db->prepare('INSERT INTO external_documents(id,provider,source_id,account_id,document_date,number,title,amount,status,raw_sha256,raw_path,context_path,batch_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$target,$d['provider'],$d['native_source_id'],$d['account_id'],$d['document_date'],$d['number'],mb_substr($d['title'],0,300),$d['amount'],$d['status'],$d['raw_sha256'],$d['raw_path'],$context,$d['batch_source_id']]);
            $this->db->prepare('INSERT INTO external_document_versions(document_id,version,raw_sha256,raw_path,batch_id) VALUES(?,1,?,?,?)')->execute([$target,$d['raw_sha256'],$d['raw_path'],$d['batch_source_id']]);
            $raw=Support::decode($this->store->read($d['raw_path'],$d['raw_sha256']));Details::save($this->db,$target,array_replace($raw,['account'=>$d['account_display'],'address'=>$d['address'],'sender'=>$d['sender'],'recipient'=>$d['recipient'],'type'=>$d['document_type']]));
            $this->db->prepare('UPDATE integration_capture_documents SET target_document_id=? WHERE capture_id=? AND source_id=?')->execute([$target,$id,$d['source_id']]);
            $this->db->prepare("UPDATE integration_capture_file_refs SET target_document_id=?,link_status='source-owner-exact' WHERE capture_id=? AND namespace='external_documents' AND owner_key=?")->execute([$target,$id,$d['source_id']]);
        }
    }
}
